      'c.story.act1.title': 'Dějství 1 - Poslední vejce', 'c.story.act1.1': 'Řád Železného kopí lovil draky, až zbylo jediné vejce.',
      'c.story.act1.2': 'Tvá matka ho ukryla hluboko ve staré sopce a sto zim ho hřála.',
      'c.story.act1.3': 'Teď jsi venku ze skořápky. Jez, rosť a uč se od ní - kraj tě ještě nesmí spatřit.',
      'c.story.act2.title': 'Dějství 2 - Vyšegrad', 'c.story.act2.1': 'Teď jsi drak: moc velký na schovávání, dost silný na odvetu.',
      'c.story.act2.2': 'Na sever od Polí teče Veltava pod Vyšegradem, hradem Řádu na skále nad řekou.',
      'c.story.act2.3': 'Vezmi, co ukradli tvému rodu, spal jejich stroje, vyprázdni jejich vozy. Práci najdeš na desce ve své jeskyni.',
